نقش سازمانی: retail_cfo (retail_cfo)

درخواست کاربر:
نقدینگی گیر کرده؛ مطالبات را باز کن. (مدیر مالی زنجیره — یاس فروشگاه‌ها)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری سازمانی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance_m",
        "aging_days"
      ]
    },
    {
      "dataset": "cash_weekly",
      "description": "موجودی نقد هفتگی شرکت",
      "dimensions": [
        "week"
      ],
      "measures": [
        "cash_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ccc",
      "description": "چرخهٔ تبدیل وجه نقد",
      "formula": "روزهای موجودی به‌علاوهٔ dso منهای dpo",
      "unit": "روز",
      "dimensions": [
        "month"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "month"
      ]
    },
    {
      "metric": "dpo",
      "description": "دورهٔ پرداخت به تأمین‌کننده",
      "formula": "بستانکاری تقسیم بر خرید روزانه",
      "unit": "روز",
      "dimensions": [
        "month"
      ]
    }
  ],
  "business_context": [
    "جنگ قیمتی با رقبای زنجیره‌ای جریان دارد",
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز",
    "مرکز توزیع واحد برای کل کشور"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ccc"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ]
  }
}

TOOL_OBSERVATION:
{
  "ccc_days": {
    "prev_month": 19,
    "curr_month": 55,
    "change": 36
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "dso",
      "dpo"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ]
  }
}

TOOL_OBSERVATION:
{
  "dso_days": {
    "prev": 28,
    "curr": 66
  },
  "dpo_days": {
    "prev": 27,
    "curr": 33
  },
  "dio_days": {
    "prev": 18,
    "curr": 22
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "receivables_aging",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
