نقش سازمانی: retail_cfo (retail_cfo)

درخواست کاربر:
تفکیک اثر افت فروش از رشد واقعی ضایعات. (مدیر مالی زنجیره — زنجیرهٔ افق کوروش)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_pnl",
      "description": "سود و زیان فروش به تفکیک دستهٔ کالا و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "revenue_m",
        "cogs_m",
        "waste_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "waste_rate",
      "description": "نرخ ضایعات",
      "formula": "ارزش ضایعات تقسیم بر فروش",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "برنامهٔ توسعهٔ سالانه شش فروشگاه جدید",
    "جنگ قیمتی با رقبای زنجیره‌ای جریان دارد",
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "waste_rate"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "waste_rate_pct": {
    "prev": 1.29,
    "curr": 2.14
  },
  "waste_m": {
    "prev": 1282,
    "curr": 2097
  },
  "revenue_m": {
    "prev": 99500,
    "curr": 98037
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_pnl",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ],
      "category": "سرمودی و فریزری"
    }
  }
}

TOOL_OBSERVATION:
{
  "category_waste_m": {
    "prev": 536,
    "curr": 1013,
    "change": 477
  }
}

نقش سازمانی: retail_cfo (retail_cfo)

درخواست کاربر:
سه شاخص بحرانی ماه را تفسیر کن و برنامهٔ سی‌روزه بده. (فروشگاه‌های زنجیره‌ای رفاه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_pnl",
      "description": "سود و زیان فروش به تفکیک دستهٔ کالا و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "revenue_m",
        "cogs_m",
        "waste_m"
      ]
    },
    {
      "dataset": "cash_weekly",
      "description": "موجودی نقد هفتگی شرکت",
      "dimensions": [
        "week"
      ],
      "measures": [
        "cash_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "gross_margin",
      "description": "حاشیهٔ ناخالص",
      "formula": "(فروش منهای بهای تمام‌شده) تقسیم بر فروش",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "month"
      ]
    }
  ],
  "business_context": [
    "فروش سازمانی و عمده به بنگاه‌ها بخشی از درآمد است",
    "سهم فروش آنلاین در حال رشد است",
    "جنگ قیمتی با رقبای زنجیره‌ای جریان دارد"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "gross_margin"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "gross_margin_pct": {
    "prev": 26.6,
    "curr": 25.1,
    "change_pp": -1.5
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cash_weekly",
    "filters": {
      "period": "last_4_weeks"
    }
  }
}

TOOL_OBSERVATION:
{
  "cash_m_weekly": [
    132,
    122,
    116,
    109
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "dso"
    ],
    "period": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "dso_days": 59,
  "sales_daily_m": 12
}

