زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_pnl",
      "description": "سود و زیان فروش به تفکیک دستهٔ کالا و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "revenue_m",
        "cogs_m",
        "waste_m"
      ]
    },
    {
      "dataset": "cash_weekly",
      "description": "موجودی نقد هفتگی شرکت",
      "dimensions": [
        "week"
      ],
      "measures": [
        "cash_m"
      ]
