  "metric_catalog": [
    {
      "metric": "gross_margin",
      "description": "حاشیهٔ ناخالص",
      "formula": "(فروش منهای بهای تمام‌شده) تقسیم بر فروش",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "month"
      ]
    }
  ],
  "business_context": [
    "فروش سازمانی و عمده به بنگاه‌ها بخشی از درآمد است",
    "جنگ قیمتی با رقبای زنجیره‌ای جریان دارد",
    "سهم فروش آنلاین در حال رشد است"
  ]
}

